namespace sv_bff7ae28fb5c47c99c97bd9382d45ff0.Services;

public enum Theme
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service — one instance per circuit, so each user gets independent state.
/// State survives enhanced navigations because the circuit (and its DI scope) stays alive.
/// </summary>
public sealed class ThemeService
{
    public Theme CurrentTheme { get; private set; } = Theme.System;
    public string AccentColor { get; private set; } = "#0d6efd";

    /// <summary>
    /// Subscribers call StateHasChanged() in their handler to re-render
    /// when any property changes.
    /// </summary>
    public event Action? OnChanged;

    public void SetTheme(Theme theme)
    {
        if (CurrentTheme == theme) return;
        CurrentTheme = theme;
        OnChanged?.Invoke();
    }

    public void SetAccentColor(string color)
    {
        if (AccentColor == color) return;
        AccentColor = color;
        OnChanged?.Invoke();
    }

    public void SetAll(Theme theme, string accentColor)
    {
        var changed = CurrentTheme != theme || AccentColor != accentColor;
        CurrentTheme = theme;
        AccentColor = accentColor;
        if (changed) OnChanged?.Invoke();
    }
}

