@*
    Interactive island that lives in the static MainLayout header.
    Because it has @rendermode InteractiveServer, it joins the circuit
    and shares the same scoped ThemeService as every other interactive component.
*@
@rendermode InteractiveServer
@implements IDisposable
@inject Services.ThemeService Theme

<span class="theme-indicator" style="color: @Theme.AccentColor;" title="Current theme">
    @GetIcon() @Theme.CurrentTheme
</span>

@code {
    protected override void OnInitialized()
        => Theme.OnChanged += HandleChanged;

    private void HandleChanged() => InvokeAsync(StateHasChanged);

    private string GetIcon() => Theme.CurrentTheme switch
    {
        Services.Theme.Light  => "☀️",
        Services.Theme.Dark   => "🌙",
        _                     => "💻"
    };

    public void Dispose() => Theme.OnChanged -= HandleChanged;
}

