    <button class="btn btn-sm btn-outline-light w-100" @onclick="CycleTheme">
        @GetIcon() @Theme.CurrentTheme
    </button>
</div>

@code {
    protected override void OnInitialized()
        => Theme.OnChanged += HandleChanged;

    private void HandleChanged() => InvokeAsync(StateHasChanged);

    private void CycleTheme()
    {
        var next = Theme.CurrentTheme switch
        {
            Services.Theme.Light  => Services.Theme.Dark,
            Services.Theme.Dark   => Services.Theme.System,
            _                     => Services.Theme.Light
        };
        Theme.SetTheme(next);
    }

    private string GetIcon() => Theme.CurrentTheme switch
    {
        Services.Theme.Light  => "☀️",
        Services.Theme.Dark   => "🌙",
        _                     => "💻"
    };

    public void Dispose() => Theme.OnChanged -= HandleChanged;
}

